 {mobileNav&&<nav className="mobile-nav" aria-label="Navigație mobilă">{[['Meniul nostru','#meniu'],['Povestea Casa Mia','#poveste'],['Galerie','#galerie'],['Evenimente','#evenimente'],['Contact','#contact']].map(([s,h])=><a key={h} href={h} onClick={()=>setMobileNav(false)}>{s}<ArrowUpRight size={18}/></a>)}<button className="mobile-event-nav" onClick={()=>openEventMenus()}>Meniuri cununie · botez · parastas <ArrowUpRight size={18}/></button><button onClick={()=>openReserve()}>Rezervă o masă <CalendarDays size={18}/></button></nav>}
