 <section className="event-menu-shortcuts" aria-label="Meniuri pentru evenimente"><div className="wrap"><div className="event-shortcut-label"><CalendarDays size={22}/><span>Meniuri pentru<br/><strong>ocazia ta</strong></span></div><div className="event-shortcut-options">{(['cununie','botez','parastas'] as EventOccasion[]).map(occasion=><button key={occasion} onClick={()=>openEventMenus(occasion)}><span>{occasion==='cununie'?'Cununie':occasion==='botez'?'Botez':'Parastas'}<small>{occasion==='parastas'?'Clasic & de post':'2 meniuri · de la 60 € / persoană'}</small></span><ArrowUpRight size={20}/></button>)}</div></div></section>
 <section className="intro-strip wrap"><div><span className="intro-number">01</span><p>Specialități cu<br/><strong>personalitate.</strong></p></div><div><span className="intro-number">02</span><p>O masă împreună.<br/><strong>O bucurie în plus.</strong></p></div><div><span className="intro-number">03</span><p>Restaurant & Events.<br/><strong>Același suflet Casa Mia.</strong></p></div></section>
 <section className="favorites section wrap" id="preferate"><div className="section-head"><div><p className="eyebrow dark">ÎNCEPE CU CEVA BUN</p><h2>Pofta are <em>preferințe.</em></h2></div><a className="underlink" href="#meniu">Vezi tot meniul <ArrowUpRight size={18}/></a></div><div className="featured-grid">{featuredNames.map((name,i)=>{const d=menu.find(d=>d.name===name)!;return <article className="featured-card" key={d.id}><button className="featured-photo" onClick={()=>choose(d)}><DishPhoto dish={d}/><span className="dish-tag">{['Specialitatea casei','Show la masă','Din mare, cu gust','Finalul dulce'][i]}</span></button><div className="featured-content"><div className="dish-meta">{d.category}<span>{d.weight}</span></div><button className="dish-title-button" onClick={()=>choose(d)}><h3>{d.name}</h3></button><div className="price-row"><strong>{money(d.price)}</strong><button className="add-button" disabled={availability[d.id]===false} onClick={()=>add(d)} aria-label={'Adaugă '+d.name}><Plus size={20}/></button></div></div></article>})}</div></section>
 <section className="order-band"><div className="wrap"><div><p className="eyebrow">POFTA TA, ÎN RITMUL TĂU</p><h2>La masă. La pachet.<br/><em>Cum îți place.</em></h2></div><div className="order-options"><a href="#meniu" onClick={()=>setMode('livrare')}><LuxuryCar size={42}/><div><h3>Livrare</h3><p>Gratuit de la 70 lei · rază 7 km.</p></div><ArrowUpRight size={23}/></a><a href="#meniu" onClick={()=>setMode('ridicare')}><PaperBag size={34}/><div><h3>Ridicare</h3><p>Comandă și ridică din restaurant.</p></div><ArrowUpRight size={23}/></a><button onClick={()=>openReserve()}><CalendarDays size={26}/><div><h3>Rezervă o masă</h3><p>Un loc pentru tine și ai tăi.</p></div><ArrowUpRight size={23}/></button></div></div></section>
