import {useEffect,useState} from 'react';
import {demoFetch} from './demoApi';
export const isDemo=import.meta.env.VITE_COMMERCE_MODE!=='live';
export type CommerceConfig={csrf:string;ready:boolean;ordersEnabled:boolean;reservationsEnabled:boolean;open:boolean;pickup:{enabled:boolean};delivery:{enabled:boolean;zones:{id:string;label:string;postal_codes:string[]}[]};paymentMethods:Record<string,string>;company:Record<string,string>;policies:{terms:string[];privacy:string[]};policyVersion:string;retentionDays:number};
export type Quote={subtotal:number;packaging:number;delivery:number;total:number;etaMinutes:number;quoteToken:string;policyVersion:string};
let config:Promise<CommerceConfig>|undefined;
export function getConfig(){return config??=window.fetch('./api/index.php?path=config',{credentials:'same-origin',cache:'no-store'}).then(async r=>{const d=await r.json();if(!r.ok)throw new Error(d.error||'Serviciul nu este disponibil.');return d;}).catch(e=>{config=undefined;throw e;});}
export async function commerceFetch(path:string,init:RequestInit={}):Promise<Response>{if(isDemo)return demoFetch(path,init);const cfg=await getConfig();const headers=new Headers(init.headers);if((init.method||'GET')==='POST')headers.set('X-CSRF-Token',cfg.csrf);const endpoint=path.replace(/^\/api\//,'');try{return await window.fetch('./api/index.php?path='+encodeURIComponent(endpoint),{...init,headers,credentials:'same-origin',cache:'no-store'});}catch{throw new Error('Conexiunea s-a întrerupt. Verifică „Comenzile mele” sau reîncearcă trimiterea cu aceleași date; cererea are protecție împotriva dublării.');}}
export function useCommerce(){const [state,setState]=useState<CommerceConfig|null>(null);const [error,setError]=useState('');useEffect(()=>{if(!isDemo)getConfig().then(setState).catch(e=>setError(e.message));},[]);return {config:state,error};}
export async function postCommerce(path:string,payload:Record<string,unknown>){const canonical={...payload};delete canonical.quoteToken;const fingerprint=[...new Uint8Array(await crypto.subtle.digest('SHA-256',new TextEncoder().encode(JSON.stringify(canonical))))].map(n=>n.toString(16).padStart(2,'0')).join('');const slot='cm-pending-'+path;let pending;try{pending=JSON.parse(sessionStorage.getItem(slot)||'null');}catch{}const key=pending?.fingerprint===fingerprint?pending.key:crypto.randomUUID();sessionStorage.setItem(slot,JSON.stringify({fingerprint,key}));const r=await commerceFetch(path,{method:'POST',headers:{'Content-Type':'application/json','Idempotency-Key':key},body:JSON.stringify(payload)});const data=await r.json();if(!r.ok)throw new Error(data.error||'Nu am putut salva cererea.');sessionStorage.removeItem(slot);return data;}
export function PriceSummary({quote}:{quote:Quote|null}){if(!quote)return null;const price=(n:number)=>(n/100).toLocaleString('ro-RO',{style:'currency',currency:'RON'});return <div className="checkout-summary"><div><span>Preparate</span><strong>{price(quote.subtotal)}</strong></div><div><span>Ambalaje</span><strong>{price(quote.packaging)}</strong></div><div><span>Livrare</span><strong>{price(quote.delivery)}</strong></div><div><span>Total de plată</span><strong>{price(quote.total)}</strong></div><p>{quote.etaMinutes?`Timp estimat: ${quote.etaMinutes} minute, după acceptarea restaurantului.`:'Timpul estimat se confirmă de restaurant.'}</p></div>}
export function FoodFacts({id}:{id:string}){const [data,setData]=useState<any>(null);useEffect(()=>{let active=true;if(!isDemo)commerceFetch('/api/catalog').then(r=>r.ok?r.json():null).then(v=>{if(active)setData(v?.items.find((d:any)=>d.id===id));}).catch(()=>{});return()=>{active=false;};},[id]);if(!data?.reviewed)return <p className="allergen-note">Pentru informații despre alergeni și valori nutriționale, contactează restaurantul la 0756 021 501.</p>;return <div className="food-facts"><h4>Alergeni</h4><p>{data.allergens.length?data.allergens.join(', '):'Nu sunt declarați alergeni în rețeta validată.'}</p><h4>Aditivi</h4><p>{data.additives.length?data.additives.join(', '):'Fără aditivi declarați.'}</p><h4>Valori nutriționale / 100 g sau 100 ml</h4><dl>{Object.entries(data.nutrition).map(([k,v])=><div key={k}><dt>{({energy_kj:'Energie (kJ)',energy_kcal:'Energie (kcal)',fat_g:'Grăsimi (g)',saturates_g:'Acizi grași saturați (g)',carbohydrates_g:'Glucide (g)',sugars_g:'Zaharuri (g)',protein_g:'Proteine (g)',salt_g:'Sare (g)'} as any)[k]||k}</dt><dd>{String(v)}</dd></div>)}</dl></div>}
export function LegalDetails({embedded=false}:{embedded?:boolean}={}){const {config}=useCommerce();const c=config?.company;return <div className={'legal-details '+(embedded?'legal-embedded':'wrap')}><details><summary>Informații comerciale și comenzi online</summary><p>Casa Mia by OAna · Strada Safirului 69R, Bragadiru. Comenzi / restaurant: 0756 021 501. Evenimente: 0761 736 599.</p>{c?.name?<p>Operator: {c.name} · CUI {c.cui} · Registrul Comerțului {c.registration} · Sediu: {c.address}.</p>:<p>Identitatea juridică și condițiile comerciale finale se completează înainte de activarea comenzilor reale.</p>}{config?.policies?.terms.map((p,i)=><p key={i}>{p}</p>)}<p>Comanda este o solicitare transmisă restaurantului. Devine acceptată după actualizarea statusului de către personal. Totalul final, taxa de livrare, ambalajele și timpul estimat se afișează înainte de trimitere. Pentru modificări, anulări, indisponibilități sau alergii, contactează restaurantul. Solicitările de rezervare se confirmă personal de echipa Casa Mia.</p></details><details><summary>Confidențialitate și servicii externe</summary>{config?.policies?.privacy.map((p,i)=><p key={i}>{p}</p>)}<p>Formularele reale folosesc numele, telefonul, detaliile comenzii sau rezervării și adresa atunci când alegi livrare, pentru procesarea solicitării. Nu include date sensibile în observații. {isDemo?'În această prezentare, comenzile sunt simulate local.':''}</p><p>{config?.retentionDays?`Termen de păstrare operațională: ${config.retentionDays} zile. `:''}Pentru acces, rectificare sau alte solicitări privind datele: {c?.privacy_email||businessEmail}. {!config?.ready&&'Lista furnizorilor, temeiurile și politica finală se validează împreună cu operatorul înainte de activare.'}</p><p>Coșul se păstrează pe dispozitiv. Sesiunea comenzilor folosește cookie-uri strict necesare în versiunea activă. Harta Google se încarcă la cerere; iconițele sociale deschid platformele externe doar la apăsare. Site-ul nu încorporează feed-uri TikTok, Facebook sau Instagram.</p></details></div>}
const businessEmail='contact@casa-mia-byoana.ro';

