export function openingState(date:Date){
 const parts=new Intl.DateTimeFormat('en-GB',{timeZone:'Europe/Bucharest',weekday:'short',hour:'2-digit',minute:'2-digit',hourCycle:'h23'}).formatToParts(date);
 const p=Object.fromEntries(parts.map(v=>[v.type,v.value]));
 const closing=p.weekday==='Fri'||p.weekday==='Sat'?23:22;
 const now=Number(p.hour)*60+Number(p.minute);
 const opening=p.weekday==='Sun'?11:10;
 const tomorrow=new Intl.DateTimeFormat('en-GB',{timeZone:'Europe/Bucharest',weekday:'short'}).format(new Date(date.getTime()+86400000));
 return {open:now>=opening*60&&now<closing*60,closing:`${closing}:00`,nextOpening:now<opening*60?`astăzi la ${opening}:00`:`mâine la ${tomorrow==='Sun'?11:10}:00`};
}
