 return <><div className={'opening-status '+(state?.open?'is-open':'')}>{state?<><i/>{state.open?'Deschis acum · până la '+state.closing:'Închis acum · deschidem '+state.nextOpening}</>:'Program restaurant'}</div><dl className="hours-list">{business.hours.map(h=><div key={h.days}><dt>{h.days}</dt><dd>{h.hours}</dd></div>)}</dl></>;
