export function VisitDetails(){const [showMap,setShowMap]=useState(false);return <div className="visit-details"><div className="visit-address"><MapPin size={28}/><p className="eyebrow dark">NE VEDEM ÎN BRAGADIRU</p><h3>Un loc pentru<br/>momentele tale.</h3><address>{business.address}</address><a className="button dark-button" href={business.directions} target="_blank" rel="noreferrer">Pornește navigarea <ArrowUpRight size={18}/></a><a className="contact-email" href={'mailto:'+business.email}><Mail size={18}/>{business.email}</a><SocialLinks className="visit-socials"/></div>{showMap?<iframe className="location-map" title="Locația Casa Mia by OAna · Strada Safirului 69R, Bragadiru" src="https://maps.google.com/maps?q=Strada%20Safirului%2069R%2C%20Bragadiru%2C%20Ilfov&z=17&output=embed" loading="lazy" referrerPolicy="no-referrer-when-downgrade" allowFullScreen/>:<div className="location-map map-consent"><MapPin size={36}/><h3>Casa Mia, pe hartă.</h3><p>Harta Google se încarcă doar când alegi să o deschizi. Astfel, Google primește datele conexiunii tale.</p><button className="button dark-button" onClick={()=>setShowMap(true)}>Afișează harta <ArrowUpRight size={18}/></button><a className="underlink" href={business.directions} target="_blank" rel="noreferrer">Deschide în Google Maps</a></div>}</div>}
