}</article>)}</div></section>)}</div>}<p className="menu-footnotes">Prețurile și cantitățile sunt preluate din meniul bar publicat de Casa Mia by OAna. Acolo unde nu este precizată cantitatea, aceasta nu este completată estimativ.</p></div></div>;
}
export function OriginalMenuGallery({kind,onChange}:{kind:OriginalKind;onChange:(kind:OriginalKind)=>void}){const m=originalMenus[kind];return <div className="panel-body"><p className="eyebrow dark">MENIURILE CASA MIA, ÎN ORIGINAL</p><h2>{m.title}.</h2><p>Deschide o pagină pentru a o vedea la rezoluția originală sau pentru a o descărca.</p><div className="original-menu-tabs">{Object.entries(originalMenus).map(([key,m])=><button key={key} onClick={()=>onChange(key as OriginalKind)} className={kind===key?'active':''} aria-pressed={kind===key}>{m.title}</button>)}</div><div className={'menu-original digital-original '+(m.images.length===1?'single':'')}>{m.images.map((src,i)=><a href={'./menus/'+src} target="_blank" rel="noreferrer" key={src}><img src={'./menus/'+src} alt={m.title+' · pagina '+(i+1)} loading="lazy"/><span>Deschide pagina {i+1} <ArrowUpRight size={16}/></span></a>)}</div></div>}
export function EventMenus({onOriginal,initialOccasion='cununie',compact=false}:{onOriginal:(kind:OriginalKind)=>void;initialOccasion?:'cununie'|'botez'|'parastas';compact?:boolean}){
 const [occasion,setOccasion]=useState<'cununie'|'botez'|'parastas'>(initialOccasion);const group=occasion==='parastas'?'parastas':'celebration';const [quote,setQuote]=useState<EventOffer|null>(null);const quoteRef=useRef<HTMLDivElement>(null);
 function request(o:EventOffer){setQuote(group==='celebration'?{...o,title:occasion==='cununie'?'Cununie':'Botez'}:o);setTimeout(()=>{quoteRef.current?.scrollIntoView({behavior:'smooth',block:'center'});quoteRef.current?.querySelector<HTMLInputElement>('input')?.focus({preventScroll:true});},50)}
