 return <div className={'event-menus wrap '+(compact?'event-menus-compact':'')} id={compact?undefined:'oferte-evenimente'}><div className="section-head"><div><p className="eyebrow">OFERTELE CASA MIA</p><h2>{compact?<>Meniuri pentru <em>{occasion}.</em></>:<>Un meniu pentru<br/><em>ocazia ta.</em></>}</h2></div><div className="event-menu-switch" role="group" aria-label="Tip eveniment">{(['cununie','botez','parastas'] as const).map(kind=><button key={kind} aria-pressed={occasion===kind} className={occasion===kind?'active':''} onClick={()=>{setOccasion(kind);setQuote(null)}}>{kind==='cununie'?'Cununie':kind==='botez'?'Botez':'Parastas'}</button>)}</div></div><div className="event-offer-grid">{eventOffers.filter(o=>group==='celebration'?o.id!=='parastas':o.id==='parastas').map(o=><article className="event-offer" key={occasion+o.subtitle}><p className="eyebrow dark">{group==='parastas'?o.title:occasion==='cununie'?'Cununie':'Botez'}</p><h3>{o.subtitle}</h3>{o.price?<div className="event-offer-price"><strong>{o.price} €</strong><span>/ persoană</span></div>:<div className="parastas-price-preview">{o.sections.filter(s=>s.price!==undefined).map(s=><span key={s.title}>{s.title}<strong>{s.price} lei / persoană</strong></span>)}{o.subtitle.includes('post')&&<span>Fel principal<strong>35 / 40 lei / persoană</strong></span>}</div>}{o.service&&<p className="event-service">+{o.service}% servicii pentru fiecare meniu agreat</p>}{o.price&&<div className="event-includes"><span>Aranjamente masă</span><span>Meniu mâncare</span><span>Open bar · max. 6 ore</span></div>}<details className="offer-details"><summary>Vezi meniul complet <ChevronDown size={18}/></summary>{o.sections.map(s=><div className="offer-course" key={s.title}><h4>{s.title}{s.price!==undefined&&<strong>{s.price} RON / persoană</strong>}</h4><ul>{s.items.map(item=><li key={item}>{item}</li>)}</ul>{s.note&&<p className="course-note">{s.note}</p>}</div>)}{o.extras&&<div className="offer-course"><h4>Opțiuni suplimentare</h4><ul>{o.extras.map(item=><li key={item}>{item}</li>)}</ul></div>}<button className="underlink" onClick={()=>onOriginal(o.id)}>Vezi meniul original <ArrowUpRight size={17}/></button></details><button className="button dark-button full" onClick={()=>request(o)}>Solicită ofertă <ArrowUpRight size={18}/></button></article>)}</div>{group==='celebration'&&<p className="event-offer-note">Pentru aniversări și evenimente corporate, <a href={'mailto:'+business.email+'?subject=Solicitare%20ofert%C4%83%20eveniment'}>solicită o ofertă personalizată</a>.</p>}<p className="event-offer-note">Disponibilitatea datei și detaliile evenimentului se stabilesc cu Oana Poteca, Event Manager: <a href="tel:0761736599">0761 736 599</a>.</p>{quote&&<div className="event-quote" ref={quoteRef}><div><p className="eyebrow">PLANIFICĂM ÎMPREUNĂ</p><h3>{quote.title}<br/><em>{quote.subtitle}</em></h3><p>Completează detaliile și pregătește emailul către Oana Poteca. Cererea se trimite din aplicația ta de email.</p><a href="tel:0761736599"><Phone size={17}/>0761 736 599</a></div><form onSubmit={draft}><div className="form-grid"><label>Nume<input name="name" required minLength={2} maxLength={80} autoComplete="name"/></label><label>Telefon<input name="phone" type="tel" required pattern="\+?[0-9 ()-]{9,20}" autoComplete="tel"/></label><label>Data evenimentului<input name="date" type="date" min={new Intl.DateTimeFormat('en-CA',{timeZone:'Europe/Bucharest',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date())} required/></label><label>Număr invitați<input name="guests" type="number" required min={1} step={1}/></label><label className="span-2">Observații<textarea name="notes" maxLength={1000} placeholder="Preferințe, opțiuni suplimentare, ce ai vrea să știm…"/></label></div><button className="button gold full" type="submit">Pregătește emailul <Mail size={18}/></button><a className="quote-mail-link" href={'mailto:'+business.email}>{business.email}</a></form></div>}</div>;
