 {selected!==null&&<div className="location-lightbox" role="dialog" aria-modal="true" aria-label={photos[selected].title} onClick={e=>{if(e.target===e.currentTarget)setSelected(null)}}><div className="location-lightbox-inner"><button className="location-close" ref={close} onClick={()=>setSelected(null)} aria-label="Închide fotografiile"><X/></button><img src={galleryPhotos[photos[selected].file]} alt={photos[selected].title}/><div className="location-lightbox-caption"><button onClick={()=>setSelected((selected+photos.length-1)%photos.length)} aria-label="Fotografia anterioară"><ArrowLeft/></button><div><h3>{photos[selected].title}</h3><p>{photos[selected].caption}</p></div><button onClick={()=>setSelected((selected+1)%photos.length)} aria-label="Fotografia următoare"><ArrowRight/></button></div></div></div>}
 </section>
