@media(max-width:700px){.location-gallery{padding-bottom:64px}.location-gallery .section-head{display:block}.location-intro{margin-top:18px;max-width:100%;font-size:14px}.location-grid{gap:12px;grid-template-columns:1fr 1fr}.location-photo{aspect-ratio:.85}.location-photo:nth-child(even){transform:translateY(18px)}.location-photo-copy{inset:auto 12px 16px;gap:6px}.location-photo-copy small{font-size:7px;letter-spacing:1px;line-height:1.5}.location-photo-copy strong{font-size:18px}.location-photo-copy>svg{width:17px;flex-shrink:0}.location-lightbox{padding:24px 12px}.location-lightbox-caption{gap:12px}.location-lightbox-caption h3{font-size:21px}.location-lightbox-caption p{font-size:12px}.location-lightbox-caption>button{width:36px;height:36px}.menu-event-direct span{line-height:1.4}}
