/* Native, low-friction touch carousel. Vertical gestures remain page scroll. */
.location-carousel{overflow:clip;padding-bottom:76px}
.location-carousel-shell{position:relative;width:100%;mask-image:linear-gradient(90deg,transparent,#000 3%,#000 97%,transparent)}
.location-track{position:relative;display:flex;gap:22px;overflow-x:auto;overflow-y:hidden;padding-inline:16%;scroll-snap-type:x mandatory;scroll-padding-inline:16%;scrollbar-width:none;-webkit-overflow-scrolling:touch;touch-action:pan-x pan-y pinch-zoom;overscroll-behavior-x:contain;overscroll-behavior-y:auto;cursor:grab;user-select:none}
.location-track::-webkit-scrollbar{display:none}.location-track:active{cursor:grabbing}
.location-slide{flex:0 0 100%;min-width:0;scroll-snap-align:center;scroll-snap-stop:normal}
.location-slide .location-photo{display:block;width:100%;aspect-ratio:4/3;border-radius:3px;transform:none;touch-action:pan-x pan-y pinch-zoom}
.location-slide .location-photo img{object-fit:cover;pointer-events:none}
.location-slide .location-photo-copy{inset:auto 32px 28px}.location-slide .location-photo-copy strong{font-size:clamp(22px,3vw,36px)}
.location-carousel-footer{display:flex;justify-content:space-between;align-items:center;gap:24px;margin-top:28px}.location-carousel-status{display:flex;align-items:center;gap:24px}.location-count{display:flex;align-items:baseline;gap:9px;font-family:'Playfair Display',Georgia,serif;font-size:30px;color:#4b4b3e;white-space:nowrap}.location-count i{font-family:var(--font);font-size:11px;font-style:normal;color:#8b7c69;letter-spacing:1px}.location-carousel-status p{font-size:13px;line-height:1.5;color:#6d5e51;max-width:390px}
.location-carousel-controls{display:flex;align-items:center;gap:15px}.location-carousel-controls>button{height:42px;width:42px;border-radius:50%;border:1px solid #89745355;display:grid;place-items:center;background:#fff8eb44;color:#69553d;transition:background .2s}.location-carousel-controls>button:hover{background:#fff8ebaa}.location-dots{display:flex;align-items:center;gap:8px}.location-dots button{width:8px;height:8px;padding:0;background:#a98c6d66;border-radius:20px;transition:width .35s,background .35s;position:relative}.location-dots button:before{content:'';position:absolute;inset:-10px -4px}.location-dots button.active{width:26px;background:#8e6a45}.location-carousel-controls>.location-autoplay{width:32px;height:32px;border-color:transparent;background:none}
@media(max-width:700px){.location-carousel{padding-bottom:50px}.location-carousel .section-head{margin-bottom:24px}.location-track{padding-inline:6%;scroll-padding-inline:6%;gap:12px}.location-carousel-shell{mask-image:linear-gradient(90deg,transparent,#000 2%,#000 98%,transparent)}.location-slide .location-photo{aspect-ratio:4/3}.location-slide .location-photo-copy{inset:auto 18px 20px}.location-slide .location-photo-copy small{font-size:8px;letter-spacing:1.7px}.location-slide .location-photo-copy strong{font-size:24px}.location-slide .location-photo-copy>svg{width:21px}.location-carousel-footer{flex-wrap:wrap;justify-content:center;gap:17px;margin-top:20px}.location-carousel-status{width:100%;gap:16px;justify-content:center}.location-carousel-status p{font-size:12px;max-width:260px}.location-count{font-size:26px}.location-carousel-controls{gap:18px}.location-carousel-controls>button{width:40px;height:40px}}

/* One gesture engine: no native snap, momentum correction or clone resets. */
.location-carousel-shell{overflow:hidden;touch-action:pan-y pinch-zoom}
.location-track{overflow:visible;padding:0;scroll-snap-type:none;scroll-padding:0;overscroll-behavior:auto;touch-action:pan-y pinch-zoom;will-change:transform}
.location-slide{flex:0 0 68%;scroll-snap-align:none;scroll-snap-stop:normal}
.location-slide .location-photo{touch-action:pan-y pinch-zoom}
