from pathlib import Path
import re,base64,hashlib,json,urllib.request,concurrent.futures
from PIL import Image
root=Path(__file__).resolve().parent.parent
media=root/'public/assets';media.mkdir(parents=True,exist_ok=True)
manifest={}
for p in (root/'src').glob('*'):
 if p.suffix not in ['.ts','.tsx','.css']:continue
 for match in re.finditer(r'data:image/(webp|png);base64,([A-Za-z0-9+/=]+)',p.read_text()):
  data=base64.b64decode(match[2]);digest=hashlib.sha256(data).hexdigest()[:16];filename='media-'+digest+'.'+match[1];target=media/filename
  if not target.exists():target.write_bytes(data)
  manifest[match[0]]=filename
  if match[1]=='webp':
   im=Image.open(target)
   for width in [480,960]:
    variant=target.with_name(target.stem+'-'+str(width)+'.webp')
    if im.width>width and not variant.exists():
     v=im.copy();v.thumbnail((width,round(im.height*width/im.width)));v.save(variant,quality=88,method=6)
# Generate any missing responsive menu thumbnails: preserve full image, no crop.
def variant(p):
 im=Image.open(p);out=p.with_name(p.stem+'-480.webp')
 if im.width>480 and not out.exists():im.thumbnail((480,480));im.save(out,quality=88,method=6)
with concurrent.futures.ThreadPoolExecutor(max_workers=8) as ex:list(ex.map(variant,[p for p in (root/'public/images/menu-complete').glob('*.webp') if '-480' not in p.stem]))
# Self-host the same fonts; keep the established typography.
fontdir=root/'public/fonts';fontdir.mkdir(exist_ok=True)
cssurl='https://fonts.googleapis.com/css2?family=DM+Sans:wght@400;500;600;700&family=Playfair+Display:ital,wght@0,400;0,500;0,600;1,400;1,500&display=swap'
if not (fontdir/'fontfaces.css').exists():
 css=urllib.request.urlopen(urllib.request.Request(cssurl,headers={'User-Agent':'Mozilla/5.0'}),timeout=30).read().decode()
 for url in set(re.findall(r'url\((https:[^)]+)\)',css)):
  ext=url.rsplit('.',1)[-1];filename=hashlib.sha256(url.encode()).hexdigest()[:16]+'.'+ext
  (fontdir/filename).write_bytes(urllib.request.urlopen(url,timeout=30).read());css=css.replace(url,'../public/fonts/'+filename)
 (fontdir/'fontfaces.css').write_text(css)
(root/'media-manifest.json').write_text(json.dumps(manifest))
print('External media:',len(set(manifest.values())),'files. Menu thumbnails completed; fonts saved locally.')

