import json,urllib.request,concurrent.futures
from pathlib import Path
root=Path(__file__).resolve().parent.parent
paths=json.loads((root/'repo-asset-paths.json').read_text())
def restore(name):
 if name.startswith('menu-complete-'): p=root/'public/images/menu-complete'/name.removeprefix('menu-complete-')
 elif name.startswith('menu-framed-'): p=root/'public/images/menu-framed'/name.removeprefix('menu-framed-')
 elif name.startswith('hero-motion-v2-'):p=root/'public/images/hero-motion-v2'/name.removeprefix('hero-motion-v2-')
 elif name.startswith('menus-'):p=root/'public/menus'/name.removeprefix('menus-')
 elif name=='favicon.svg':p=root/'public'/name
 else:p=root/'public/images'/name
 if p.exists():return
 p.parent.mkdir(parents=True,exist_ok=True)
 p.write_bytes(urllib.request.urlopen('https://raw.githubusercontent.com/shultzstakes-ui/casa-mia-demo/main/'+name,timeout=30).read())
with concurrent.futures.ThreadPoolExecutor(max_workers=10) as ex:list(ex.map(restore,paths))
print('Restored',len(paths),'public image assets.')

