async function loadCatalog(){const d=await api('operator/catalog');const availability=new Map(d.availability.map(i=>[i.id,Number(i.available)!==0]));$('catalog').replaceChildren(...d.items.map(i=>{const label=node('label');label.className='stock';const check=node('input');check.type='checkbox';check.checked=availability.get(i.id)!==false;check.addEventListener('change',async()=>{check.disabled=true;try{await api('operator/availability',{id:i.id,available:check.checked});}catch(e){check.checked=!check.checked;message(e.message);}finally{check.disabled=false;}});label.append(check,node('span',i.name+(i.reviewed?'':' · informații de validat')));return label;}));}
